// Exercise collection decoding, response contracts, and failure preservation with an in-memory repository.
// Generated by Codex and not thoroughly checked for correctness.
func TestCollectionHandlers(t *testing.T) {
	gin.SetMode(gin.TestMode)
	for _, tc := range []struct {
		suffix, body string
		status       int
	}{
		{"/move", `{"problem_ids":["A"],"before_problem_id":"B"}`, 200},
		{"/move", `{"problem_ids":["A"],"after_problem_id":"B"}`, 200},
		{"/move", `{"problem_ids":["A"],"before_problem_id":"missing"}`, 409},
		{"/move", `{"problem_ids":["A"],"before_problem_id":"A"}`, 400},
		{"/move", `{"problem_ids":["A"],"unknown":true}`, 400},
		{"", `{"items":[{"problem_id":"C","notes":"hi"}]}`, 200},
		{"", `{"items":[{"problem_id":"A"}]}`, 200},
		{"", `{"items":[{"problem_id":"C"},{"problem_id":"A"}]}`, 200},
		{"", `{"items":[{"problem_id":"C"},{"problem_id":"C"}]}`, 200},
		{"", `{"items":[{"problem_id":"judge:series/problem"}]}`, 200},
		{"", `{"items":[{"problem_id":"C"}],"before_problem_id":"missing"}`, 404},
		{"", `{"items":[{"problem_id":"C"}],"before_problem_id":""}`, 404},
		{"/remove", `{"problem_ids":["missing:opaque/key"]}`, 200},
		{"", `{"items":[{"problem_id":"C"}],"before_problem_id":3}`, 400},
		{"", `{"items":[{"problem_id":"C"}],"after_problem_id":"B"}`, 400},
		{"", `{"items":[{"problem_id":"C","position":1}]}`, 400},
		{"", `{"items":[{"problem_id":"C","status":"bad"}]}`, 400},
		{"", `{"items":[{"problem_id":"C","notes":"\u0000"}]}`, 400},
		{"/remove", `{"problem_ids":["A"]}`, 200},
		{"/remove", `{"problem_ids":["A","B","missing"]}`, 200},
		{"/remove", `{"problem_ids":["A","A"]}`, 400},
		{"/remove", `{"problem_ids":[]}`, 400},
		{"/remove", `{"problem_ids":5}`, 400},
		{"/move", `{"problem_ids":5}`, 400},
		{"/move", `{"problem_ids":["A","A"]}`, 400},
		{"/move", `{"moves":[{"problem_id":"A"}]}`, 400},
		{"", `{"items":5}`, 400},
		{"", `{"items":[{"problem_id":"C","notes":"` + string([]byte{0xff}) + `"}]}`, 400},
		{"/move", `{`, 400},
		{"", `{} {}`, 400},
	} {
		t.Run(tc.suffix+tc.body, func(t *testing.T) {
			repository := newMockRepository()
			repository.expectedContext = t.Context()
			for index, id := range []string{"A", "B"} {
				item := newListItemFixture()
				item.ProblemId = id
				item.Position = int64(index+1) * configs.ListPositionGap
				repository.storeItem(item)
			}
			before := map[string]items.ListItem{}
			for id, item := range repository.items[testListID] {
				before[id] = item
			}
			response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPost, fmt.Sprintf("%s/%d/items%s", testListsPath, testListID, tc.suffix), tc.body)
			assertResponseStatus(t, response, tc.status)
			if tc.status >= 400 && !reflect.DeepEqual(before, repository.items[testListID]) {
				t.Fatal("failed request changed records")
			}
			if tc.status == 200 {
				var result items.CollectionResult
				if err := json.Unmarshal(response.Body.Bytes(), &result); err != nil {
					t.Fatal(err)
				}
				wantPositions := 1
				if tc.suffix == "" {
					wantPositions = len(result.Added)
				}
				if tc.suffix == "/remove" {
					wantPositions = 0
				}
				if result.Order == nil || len(result.Order) != wantPositions {
					t.Fatalf("response included unrelated positions: %+v", result.Order)
				}
			}
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestMoveSelectionUsesOneDestination(t *testing.T) {
	gin.SetMode(gin.TestMode)
	repository := newMockRepository()
	repository.expectedContext = t.Context()
	for index, id := range []string{"A", "B", "C"} {
		item := newListItemFixture()
		item.ProblemId = id
		item.Position = int64(index+1) * configs.ListPositionGap
		repository.storeItem(item)
	}
	response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPost,
		itemCollectionPath(testListID)+"/move", `{"problem_ids":["C"," A ","A"],"after_problem_id":"B"}`)
	assertResponseStatus(t, response, http.StatusOK)
	var result items.CollectionResult
	if err := json.Unmarshal(response.Body.Bytes(), &result); err != nil {
		t.Fatal(err)
	}
	want := []items.OrderedItem{
		{ProblemID: "C", Position: 3 * configs.ListPositionGap},
		{ProblemID: "A", Position: 5 * configs.ListPositionGap},
	}
	if result.Rebalanced || !reflect.DeepEqual(result.Order, want) || !reflect.DeepEqual(result.Absent, []string{" A "}) {
		t.Fatalf("move selection response=%+v", result)
	}
}

// Verify one anchor applies to the complete batch while existing items retain their data.
// Generated by Codex and not thoroughly checked for correctness.
func TestAddBatchBeforeOneAnchor(t *testing.T) {
	gin.SetMode(gin.TestMode)
	repository := newMockRepository()
	repository.expectedContext = t.Context()
	for index, id := range []string{"A", "B", "D"} {
		item := newListItemFixture()
		item.ProblemId = id
		item.Position = int64(index+1) * configs.ListPositionGap
		repository.storeItem(item)
	}
	original := repository.items[testListID]["A"]
	response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPost, itemCollectionPath(testListID), `{"before_problem_id":"B","items":[{"problem_id":"C"},{"problem_id":"A","notes":"Ignored"},{"problem_id":"E"}]}`)
	assertResponseStatus(t, response, http.StatusOK)
	var result items.CollectionResult
	if err := json.Unmarshal(response.Body.Bytes(), &result); err != nil {
		t.Fatal(err)
	}
	want := []string{"C", "E"}
	if len(result.Order) != len(want) || len(result.Added) != 2 || !reflect.DeepEqual(result.Duplicates, []string{"A"}) {
		t.Fatal(result)
	}
	for index, item := range result.Order {
		if item.ProblemID != want[index] {
			t.Fatal(result.Order)
		}
	}
	if result.Added[0].Position != configs.ListPositionGap+configs.ListPositionGap/4 || result.Added[1].Position != configs.ListPositionGap+3*(configs.ListPositionGap/4) {
		t.Fatal(result.Added)
	}
	if !reflect.DeepEqual(original, repository.items[testListID]["A"]) {
		t.Fatal("existing item changed")
	}
}

// Verify omitted and null anchors insert before the first saved item without moving it.
// Generated by Codex and not thoroughly checked for correctness.
func TestAddWithoutAnchorPrependsBatch(t *testing.T) {
	gin.SetMode(gin.TestMode)
	for _, body := range []string{
		`{"items":[{"problem_id":"B"},{"problem_id":"C"}]}`,
		`{"before_problem_id":null,"items":[{"problem_id":"B"},{"problem_id":"C"}]}`,
	} {
		t.Run(body, func(t *testing.T) {
			repository := newMockRepository()
			repository.expectedContext = t.Context()
			original := newListItemFixture()
			original.ProblemId = "A"
			original.Position = 3 * configs.ListPositionGap
			repository.storeItem(original)
			response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPost, itemCollectionPath(testListID), body)
			assertResponseStatus(t, response, http.StatusOK)
			var result items.CollectionResult
			if err := json.Unmarshal(response.Body.Bytes(), &result); err != nil {
				t.Fatal(err)
			}
			want := []items.OrderedItem{{ProblemID: "B", Position: configs.ListPositionGap}, {ProblemID: "C", Position: 2 * configs.ListPositionGap}}
			if result.Rebalanced || len(result.Added) != 2 || !reflect.DeepEqual(result.Order, want) {
				t.Fatalf("prepend response=%+v", result)
			}
			if !reflect.DeepEqual(repository.items[testListID]["A"], original) {
				t.Fatal("prepend changed existing item")
			}
		})
	}
}

// Verify capacity is checked for every input before anchor lookup or duplicate handling.
// Generated by Codex and not thoroughly checked for correctness.
func TestAddRejectsWholeRequestWhenProjectedCountExceedsQuota(t *testing.T) {
	gin.SetMode(gin.TestMode)
	repository := newMockRepository()
	for index := range limits.ItemsPerList - 1 {
		item := newListItemFixture()
		item.ProblemId = fmt.Sprintf("seed-%d", index)
		item.Position = int64(index+1) * configs.ListPositionGap
		repository.storeItem(item)
	}
	for _, body := range []string{
		`{"items":[{"problem_id":"seed-0"},{"problem_id":"new"}]}`,
		`{"before_problem_id":"missing","items":[{"problem_id":"seed-0"},{"problem_id":"seed-1"}]}`,
	} {
		repository.expectedContext = t.Context()
		response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPost, itemCollectionPath(testListID), body)
		assertResponseStatus(t, response, http.StatusConflict)
		var result struct {
			Error string `json:"error"`
		}
		if err := json.Unmarshal(response.Body.Bytes(), &result); err != nil || result.Error != limits.ErrItemQuota.Error() {
			t.Fatalf("response=%s error=%v", response.Body.String(), err)
		}
		if len(repository.items[testListID]) != limits.ItemsPerList-1 {
			t.Fatal("over-capacity request changed saved items")
		}
	}
}

// Verify invalid list identifiers and inaccessible lists produce stable HTTP errors.
// Generated by Codex and not thoroughly checked for correctness.
func TestCollectionHandlersRejectInvalidOrUnownedList(t *testing.T) {
	gin.SetMode(gin.TestMode)
	for _, tc := range []struct{ suffix, body string }{
		{"", `{"items":[{"problem_id":"A"}]}`},
		{"/move", `{"problem_ids":["A"]}`},
		{"/remove", `{"problem_ids":["A"]}`},
	} {
		for _, id := range []string{"invalid", fmt.Sprint(testListID)} {
			repository := newMockRepository()
			repository.expectedContext = t.Context()
			clearLists(repository)
			response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPost, fmt.Sprintf("%s/%s/items%s", testListsPath, id, tc.suffix), tc.body)
			want := http.StatusNotFound
			if id == "invalid" {
				want = http.StatusBadRequest
			}
			assertResponseStatus(t, response, want)
		}
	}
}

// BulkAdd models anchored insertion or default prepending; database atomicity is tested separately.
func (repository mockListItemRepository) BulkAdd(ctx context.Context, userID, listID int64, input []items.ListItem, before *string) (*items.CollectionResult, error) {
	if len(input) == 0 {
		return nil, items.ErrInvalidOperation
	}
	for _, item := range input {
		if item.ProblemId == "" {
			return nil, items.ErrInvalidOperation
		}
		if err := item.Practice.Normalize(); err != nil {
			return nil, err
		}
	}
	repository.contextMismatch = repository.contextMismatch || ctx != repository.expectedContext
	for _, item := range input {
		repository.record(repositoryCall{operation: createListItemOperation, userID: userID, listID: listID, problemID: item.ProblemId})
	}
	if err := repository.operationErrors[createListItemOperation]; err != nil {
		return nil, err
	}
	if _, ok := repository.ownedList(userID, listID); !ok {
		return nil, items.ErrListNotFound
	}
	if len(repository.items[listID])+len(input) > limits.ItemsPerList {
		return nil, limits.ErrItemQuota
	}
	result := &items.CollectionResult{Order: []items.OrderedItem{}}
	last := int64(0)
	var upper *int64
	if before != nil {
		anchor, ok := repository.items[listID][*before]
		if !ok {
			return nil, items.ErrItemNotFound
		}
		upper = &anchor.Position
		for _, item := range repository.items[listID] {
			if item.Position > last && item.Position < *upper {
				last = item.Position
			}
		}
	} else {
		for _, item := range repository.items[listID] {
			if upper == nil || item.Position < *upper {
				position := item.Position
				upper = &position
			}
		}
	}
	ranks := mockRanks(last, upper, len(input))
	if ranks == nil {
		return nil, items.ErrInvalidOperation
	}
	for index, item := range input {
		if _, exists := repository.items[listID][item.ProblemId]; exists {
			result.Duplicates = append(result.Duplicates, item.ProblemId)
			continue
		}
		item.Position = ranks[index]
		item.ListId = listID
		item.CreatedAt = testItemCreatedAt()
		repository.storeItem(item)
		result.Added = append(result.Added, item)
		result.Order = append(result.Order, items.OrderedItem{ProblemID: item.ProblemId, Position: item.Position})
	}
	sort.Slice(result.Order, func(i, j int) bool { return result.Order[i].Position < result.Order[j].Position })
	return result, nil
}

// MoveItems models a group move in memory for the HTTP contract tests.
func (repository mockListItemRepository) MoveItems(ctx context.Context, userID, listID int64, move items.Move) (*items.CollectionResult, error) {
	stored, err := repository.GetItems(ctx, userID, listID)
	if err != nil {
		return nil, err
	}
	selectedIDs := make(map[string]bool, len(move.ProblemIDs))
	for _, id := range move.ProblemIDs {
		selectedIDs[id] = true
	}
	var remaining []items.ListItem
	for _, item := range stored {
		if !selectedIDs[item.ProblemId] {
			remaining = append(remaining, item)
		}
	}
	destination := len(remaining)
	if move.Before != nil || move.After != nil {
		destination = -1
		for index, item := range remaining {
			if move.Before != nil && item.ProblemId == *move.Before {
				destination = index
				break
			}
			if move.After != nil && item.ProblemId == *move.After {
				destination = index + 1
				break
			}
		}
		if destination < 0 {
			return nil, items.ErrOrderConflict
		}
	}
	var left int64
	var right *int64
	if destination > 0 {
		left = remaining[destination-1].Position
	}
	if destination < len(remaining) {
		right = &remaining[destination].Position
	}
	ranks := mockRanks(left, right, len(move.ProblemIDs))
	if ranks == nil {
		return nil, items.ErrInvalidOperation
	}
	result := &items.CollectionResult{Order: []items.OrderedItem{}}
	for index, id := range move.ProblemIDs {
		item, exists := repository.items[listID][id]
		if !exists {
			result.Absent = append(result.Absent, id)
			continue
		}
		item.Position = ranks[index]
		repository.storeItem(item)
		result.Order = append(result.Order, items.OrderedItem{ProblemID: id, Position: item.Position})
	}
	return result, nil
}

// mockRanks supplies positions for the roomy intervals used by the handler fixtures.
func mockRanks(left int64, right *int64, count int) []int64 {
	gap := configs.ListPositionGap
	if right == nil {
		left -= left % gap
	} else {
		gap = (*right - left) / int64(count+1)
	}
	if gap < 1 {
		return nil
	}
	ranks := make([]int64, count)
	for index := range ranks {
		ranks[index] = left + int64(index+1)*gap
	}
	return ranks
}

// BulkRemove validates and removes selected items from shared mock state as one operation.
func (repository mockListItemRepository) BulkRemove(ctx context.Context, userID, listID int64, ids []string) (*items.CollectionResult, error) {
	if len(ids) == 0 {
		return nil, items.ErrInvalidOperation
	}
	seen := map[string]bool{}
	for _, id := range ids {
		if id == "" || seen[id] {
			return nil, items.ErrInvalidOperation
		}
		seen[id] = true
	}
	repository.contextMismatch = repository.contextMismatch || ctx != repository.expectedContext
	for _, id := range ids {
		repository.record(repositoryCall{operation: deleteListItemOperation, userID: userID, listID: listID, problemID: id})
	}
	if err := repository.operationErrors[deleteListItemOperation]; err != nil {
		return nil, err
	}
	if _, ok := repository.ownedList(userID, listID); !ok {
		return nil, items.ErrListNotFound
	}
	result := &items.CollectionResult{Order: []items.OrderedItem{}}
	for _, id := range ids {
		if _, exists := repository.items[listID][id]; exists {
			delete(repository.items[listID], id)
			result.Removed = append(result.Removed, id)
		} else {
			result.Absent = append(result.Absent, id)
		}
	}
	return result, nil
}
